{"path":"lib/books.js","content":"import { promises as fs } from "node:fs";
import path from "node:path";
import { randomUUID } from "node:crypto";

// Where books are stored. Override with BOOKS_FILE (used by tests).
function dataFile() {
  return process.env.BOOKS_FILE || path.join(process.cwd(), "data", "books.json");
}

export const LIMITS = { title: 200, author: 200, notes: 5000 };

async function readAll() {
  try {
    const raw = await fs.readFile(dataFile(), "utf8");
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (err) {
    if (err.code === "ENOENT") return [];
    throw err;
  }
}

// Write to a temp file then rename, so a crash mid-write can't corrupt the file.
async function writeAll(books) {
  const file = dataFile();
  await fs.mkdir(path.dirname(file), { recursive: true });
  const tmp = `${file}.${process.pid}.${Date.now()}.tmp`;
  await fs.writeFile(tmp, JSON.stringify(books, null, 2) + "\n", "utf8");
  await fs.rename(tmp, file);
}

// Serialize read-modify-write cycles so two quick requests can't overwrite each other.
let queue = Promise.resolve();
function withLock(fn) {
  const run = queue.then(fn, fn);
  queue = run.catch(() => {});
  return run;
}

function clean(value, max) {
  return String(value ?? "").trim().slice(0, max);
}

export async function listBooks() {
  const books = await readAll();
  const byNewest = (a, b) => (b.addedAt || "").localeCompare(a.addedAt || "");
  const byFinished = (a, b) => (b.finishedAt || "").localeCompare(a.finishedAt || "");
  return {
    reading: books.filter((b) => !b.finishedAt).sort(byNewest),
    finished: books.filter((b) => b.finishedAt).sort(byFinished),
  };
}

export async function getBook(id) {
  const books = await readAll();
  return books.find((b) => b.id === id) ?? null;
}

export function addBook(input) {
  const title = clean(input.title, LIMITS.title);
  const author = clean(input.author, LIMITS.author);
  const notes = clean(input.notes, LIMITS.notes);
  if (!title) throw new Error("Title is required");

  return withLock(async () => {
    const books = await readAll();
    const book = {
      id: randomUUID(),
      title,
      author,
      notes,
      addedAt: new Date().toISOString(),
      finishedAt: null,
    };
    books.push(book);
    await writeAll(books);
    return book;
  });
}

export function finishBook(id) {
  return withLock(async () => {
    const books = await readAll();
    const book = books.find((b) => b.id === id);
    if (!book) return null;
    if (!book.finishedAt) {
      book.finishedAt = new Date().toISOString();
      await writeAll(books);
    }
    return book;
  });
}
"}

