import { useActionState, useEffect, useRef } from "react";
import { addBookAction } from "./actions";

export default function AddBookForm() {
  const [state, formAction, pending] = useActionState(addBookAction, { error: null });
  const formRef = useRef(null);

  // Clear the form after a successful add.
  useEffect(() => {
    if (state.ok) formRef.current?.reset();
  }, [state.ok]);

  return (
    <form ref={formRef} action={formAction} className="add-form">
      <label>
        Title
        <input name="title" required maxLength={200} />
      </label>
      <label>
        Author
        <input name="author" maxLength={200} />
      </label>
      <label>
        Notes
        <textarea name="notes" rows={3} maxLength={5000} />
      </label>
      {state.error && <p className="error">{state.error}</p>}
      <button type="submit" disabled={pending}>
        {pending ? "Adding..." : "Add book"}
      </button>
    </form>
  );
}
"}

