{"path":"lib/books.test.js","content":"import { describe, it, expect, beforeEach } from "vitest";
import { mkdtempSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { addBook, finishBook, getBook, listBooks } from "./books.js";

beforeEach(() => {
  const dir = mkdtempSync(path.join(tmpdir(), "books-"));
  process.env.BOOKS_FILE = path.join(dir, "books.json");
});

describe("books store", () => {
  it("starts empty when no file exists", async () => {
    expect(await listBooks()).toEqual({ reading: [], finished: [] });
  });

  it("adds a book and persists it to the JSON file", async () => {
    const book = await addBook({ title: "  Dune ", author: "Frank Herbert", notes: "Spice." });
    expect(book.title).toBe("Dune");
    expect(await getBook(book.id)).toEqual(book);
    const onDisk = JSON.parse(readFileSync(process.env.BOOKS_FILE, "utf8"));
    expect(onDisk).toEqual([book]);
  });

  it("requires a title", async () => {
    expect(() => addBook({ title: "   " })).toThrow("Title is required");
  });

  it("moves a book to finished", async () => {
    const book = await addBook({ title: "Emma" });
    expect((await listBooks()).reading).toHaveLength(1);
    await finishBook(book.id);
    const { reading, finished } = await listBooks();
    expect(reading).toHaveLength(0);
    expect(finished[0].id).toBe(book.id);
    expect(finished[0].finishedAt).toBeTruthy();
  });

  it("returns null for unknown ids", async () => {
    expect(await getBook("nope")).toBeNull();
    expect(await finishBook("nope")).toBeNull();
  });

  it("does not lose books added concurrently", async () => {
    await Promise.all(Array.from({ length: 20 }, (_, i) => addBook({ title: `Book ${i}` })));
    expect((await listBooks()).reading).toHaveLength(20);
  });
});
"}

